const SOURCE = Buffer.from("", "base64");

module.exports = function downloadFixedApp(req, res) {
  res.statusCode = 200;
  res.setHeader("Content-Type", "application/javascript; charset=utf-8");
  res.setHeader("Content-Disposition", 'attachment; filename="app.js"');
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Oyukwan-Source-Version", "2026-08-30-animal-boundary-discovery-v7");
  res.end(SOURCE);
};
